import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// DIGITALL MAX · GMN Tope 03 (produto de R$ 10). Motion vertical de venda, roteiro do cliente, narração o locutor (src/voz-v1.mp3, 26,6 s).
// Jeito: motion. O material são telas do sistema e a arte do produto, não fotos: o problema é desenhado (sem marca)
// e as telas do cliente só entram depois que a fala apresenta o GMN Tope 03.
// Identidade: a mesma do vídeo anterior da marca (Renato-GoogleNota): preto, papel #F4F2EE e laranja #F29F05 chapado, Montserrat.
// Tempos = tempos da locução v1 (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada).
// v2 (19/10, "tirar todas as pausas"): a voz sem pausas (edit/voz-v1-sem-pausas.wav, 20,3 s) toca no vídeo; WARP converte o
// tempo novo no tempo da v1 (cada pausa cortada vira uma passagem acelerada curta), sem reescrever os tempos das cenas.

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const DGT_FPS = 30;
const LEAD = 0.2;
export const DGT_FRAMES = Math.round((28.6 + LEAD) * DGT_FPS);
// [tempo novo, tempo da voz v1] (tools/cortar_voz.py → edit/tabela-v1.json)
const WARP: [number, number][] = [[0.0, 0.04], [2.19, 2.23], [2.34, 3.05], [2.49, 3.49], [4.02, 5.02], [4.22, 6.01], [5.4, 7.19], [5.6, 7.63], [6.08, 8.11], [6.28, 9.04], [10.83, 13.59], [11.03, 14.09], [11.62, 14.68], [11.82, 15.16], [12.64, 15.98], [12.84, 16.67], [13.47, 17.3], [13.67, 17.82], [14.04, 18.19], [14.24, 19.16], [16.44, 21.36], [16.64, 22.14], [17.93, 23.43], [18.13, 24.12], [18.77, 24.76], [18.97, 25.15], [19.78, 25.96], [19.98, 26.29]];
const toOld = (tn: number) => {
  if (tn <= WARP[0][0]) return tn + WARP[0][1] - WARP[0][0];
  for (let i = 1; i < WARP.length; i++) {
    const [n0, o0] = WARP[i - 1], [n1, o1] = WARP[i];
    if (tn <= n1) return o0 + ((tn - n0) / (n1 - n0)) * (o1 - o0);
  }
  const [nl, ol] = WARP[WARP.length - 1];
  return tn - nl + ol;
};
export const DGT2_FRAMES = Math.round((22.3 + LEAD) * DGT_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BLACK = "#0A0A0A";
const CARD = "#161616";
const LINE = "#2A2A2A";
const OR = "#F29F05";
const WHITE = "#FFFFFF";
const GREY = "#8C8C8C";
const RED = "#E0483E";
const PAPER = "#F4F2EE";
const INK = "#1A1A1A";
const SHADOW = "0 30px 70px rgba(0,0,0,0.14), 0 6px 16px rgba(0,0,0,0.07)";

const T2 = 3.0, T3 = 8.45, T4 = 10.55, T5 = 12.5, T6 = 13.95, T7 = 16.5, T8 = 18.55, T9 = 23.6;

const blurIn = (t: number, at: number, out?: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 12).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

// linhas de título centralizadas; a de destaque vem numa faixa laranja
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; out?: number; hlBg?: string; hlColor?: string; color?: string }> = ({ t, items, size, top, out, hlBg = OR, hlColor = BLACK, color = WHITE }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.1 }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? hlColor : color, textTransform: hl ? "uppercase" : undefined, ...(hl ? { background: hlBg, padding: `${size * 0.04}px ${size * 0.26}px ${size * 0.1}px`, borderRadius: size * 0.2 } : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// câmera da cena: escala e deslocamento de a até b
const Cam: React.FC<{ t: number; a: number; b: number; s0?: number; s1?: number; y0?: number; y1?: number; x0?: number; x1?: number; children: React.ReactNode }> = ({ t, a, b, s0 = 1.06, s1 = 1, y0 = 0, y1 = 0, x0 = 0, x1 = 0, children }) => {
  const p = io(t, a, b);
  return (
    <AbsoluteFill style={{ transform: `translate(${(x0 + (x1 - x0) * p).toFixed(1)}px, ${(y0 + (y1 - y0) * p).toFixed(1)}px) scale(${(s0 + (s1 - s0) * p).toFixed(4)})` }}>{children}</AbsoluteFill>
  );
};

// ───────── ícones ─────────
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoStore = ({ s, c }: { s: number; c: string }) => sv(s, c, <><path d="M4 9.5l1.5-5h13l1.5 5" /><path d="M4 9.5c0 1.500 1.200 2.500 2.700 2.500S9.300 11 9.300 9.500c0 1.500 1.200 2.500 2.700 2.500s2.700-1 2.700-2.500c0 1.500 1.200 2.500 2.700 2.500S20 11 20 9.500" /><path d="M5.500 12v7.500h13V12M10 19.500v-4.500h4v4.500" /></>);
const IcoSearch = ({ s, c }: { s: number; c: string }) => sv(s, c, <><circle cx="10.500" cy="10.500" r="6.500" /><path d="M15.500 15.500L21 21" /></>, 2.4);
const Star: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 2.8l2.800 5.800 6.300.900-4.600 4.400 1.100 6.300L12 17.200l-5.600 3 1.100-6.300L2.900 9.500l6.300-.900z" fill={c} /></svg>
);
const Pin: React.FC<{ s: number; c: string; children?: React.ReactNode }> = ({ s, c, children }) => (
  <div style={{ position: "relative", width: s, height: s * 1.3 }}>
    <svg width={s} height={s * 1.3} viewBox="0 0 40 52" style={{ position: "absolute", inset: 0 }}><path d="M20 51C20 51 3 31 3 19.500 3 9.700 10.600 2 20 2s17 7.700 17 17.500C37 31 20 51 20 51z" fill={c} /><circle cx="20" cy="19" r="7.500" fill={BLACK} /></svg>
    {children}
  </div>
);

// cartão de resultado de busca (ilustrativo, sem marca)
const Card: React.FC<{ name: string; you?: boolean; dim?: number; light?: boolean; style?: React.CSSProperties }> = ({ name, you, dim = 0, light, style }) => (
  <div style={{ position: "absolute", left: 240, width: 720, height: 176, borderRadius: 30, background: light ? WHITE : CARD, boxShadow: light ? SHADOW : undefined, border: `${you ? 5 : light ? 0 : 3}px solid ${you ? OR : LINE}`, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 30, padding: "0 34px", fontFamily: F, filter: dim ? `grayscale(${dim}) brightness(${1 - dim * 0.45})` : undefined, ...style }}>
    <div style={{ width: 104, height: 104, borderRadius: 26, background: you ? OR : light ? "#F0EEE9" : "#242424", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><IcoStore s={60} c={you ? BLACK : light ? OR : GREY} /></div>
    <div>
      <div style={{ fontWeight: 800, fontSize: 50, color: you ? (light ? INK : OR) : light ? INK : WHITE, letterSpacing: "-0.03em", whiteSpace: "nowrap" }}>{name}</div>
      <div style={{ display: "flex", gap: 6, marginTop: 10 }}>{[0, 1, 2, 3, 4].map((i) => <Star key={i} s={36} c={you ? OR : light ? OR : "#5A5A5A"} />)}</div>
    </div>
  </div>
);
const SlotNum: React.FC<{ n: number; top: number; on: boolean; light?: boolean; style?: React.CSSProperties }> = ({ n, top, on, light, style }) => (
  <div style={{ position: "absolute", left: 120, top: top + 38, width: 100, height: 100, borderRadius: 100, background: on ? OR : light ? "#E4E1DA" : "#1E1E1E", color: on ? BLACK : light ? INK : GREY, fontFamily: F, fontWeight: 800, fontSize: 54, display: "flex", alignItems: "center", justifyContent: "center", ...style }}>{n}</div>
);

// tela do sistema: ocupa a parte de cima do quadro inteira, com degradê para o preto onde entra o lettering
const Screen: React.FC<{ src: string; t: number; a: number; b: number; pos0: string; pos1: string; s0?: number; s1?: number; h?: number; origin?: string }> = ({ src, t, a, b, pos0, pos1, s0 = 1.0, s1 = 1.08, h = 1300, origin = "50% 50%" }) => {
  const p = lin(t, a, b);
  const [x0, y0] = pos0.split(" ").map(parseFloat);
  const [x1, y1] = pos1.split(" ").map(parseFloat);
  return (
    <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: h, overflow: "hidden" }}>
      <Img src={staticFile(`digitall/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: `${(x0 + (x1 - x0) * p).toFixed(2)}% ${(y0 + (y1 - y0) * p).toFixed(2)}%`, transformOrigin: origin, transform: `scale(${(s0 + (s1 - s0) * p).toFixed(4)})` }} />
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 420, background: `linear-gradient(to bottom, rgba(10,10,10,0), ${BLACK})` }} />
    </div>
  );
};
// lettering de baixo: bloco laranja com letra preta grande, troca no mesmo lugar
const Letter: React.FC<{ t: number; text: string; at: number; out?: number; size?: number; top?: number; solid?: boolean }> = ({ t, text, at, out, size = 130, top = 1400, solid = true }) => {
  const e = pop(t, at, 0.42);
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", opacity: Math.min(1, e * 2) * (1 - o) }}>
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.04em", whiteSpace: "nowrap", color: solid ? BLACK : WHITE, background: solid ? OR : "transparent", padding: `${size * 0.06}px ${size * 0.3}px ${size * 0.12}px`, borderRadius: size * 0.18, transform: `translateY(${((1 - e) * 60).toFixed(1)}px) scale(${(0.86 + 0.14 * e).toFixed(4)})`, filter: `blur(${(o * 10).toFixed(1)}px)` }}>{text}</div>
    </div>
  );
};

// ───────── cena 1 · perdendo dinheiro todo dia (problema, desenhado) ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const pts = [[80, 1010], [260, 1080], [380, 1040], [560, 1250], [700, 1200], [860, 1450], [1000, 1520]];
  const d = "M" + pts.map((p) => p.join(" ")).join(" L");
  const draw = k(t, -0.2, 1.6);
  const coins = [[200, 1045, 0.2], [380, 1045, 0.55], [520, 1210, 0.95], [690, 1205, 1.35], [860, 1450, 1.75], [300, 1075, 2.15], [600, 1225, 2.5]];
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Cam t={t} a={1.2} b={3.1} s0={1.0} s1={0.97} y0={0} y1={10}>
      <Cam t={t} a={-0.2} b={1.3} s0={1.35} s1={1.0} y0={160} y1={0}>
        <Lines t={t} top={250} size={118} items={[["Você tá", 0.02], ["perdendo", 0.42], ["dinheiro", 0.95, true], ["todo dia", 1.6]]} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
          <path d={d} fill="none" stroke={RED} strokeWidth={16} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={`${draw.toFixed(3)} 1`} />
          {draw > 0.97 ? <path d="M1000 1520 l-70 -6 M1000 1520 l-26 -64" stroke={RED} strokeWidth={16} strokeLinecap="round" opacity={lin(t, 1.7, 1.85)} /> : null}
        </svg>
        {coins.map(([x, y, at], i) => {
          const f = lin(t, at, at + 1.1);
          if (t < at) return null;
          return (
            <div key={i} style={{ position: "absolute", left: x - 60, top: y - 60 + f * f * 620, width: 120, height: 120, borderRadius: 120, background: OR, border: `8px solid #C77F00`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 42, color: BLACK, opacity: (1 - f) * pop(t, at, 0.3), transform: `rotate(${(f * (i % 2 ? 160 : -160)).toFixed(1)}deg) scale(${(0.6 + 0.4 * pop(t, at, 0.3)).toFixed(3)})` }}>R$</div>
          );
        })}
      </Cam>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · o cliente pesquisa e acha o concorrente ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const q = "perto de mim";
  const typed = q.slice(0, Math.floor(lin(t, 3.55, 4.7) * q.length));
  const lose = io(t, 7.62, 8.1);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <Cam t={t} a={5.0} b={T3 + 0.4} s0={1.0} s1={1.07} y0={0} y1={-30}>
      <Cam t={t} a={T2} b={5.1} s0={1.16} s1={1.0} y0={220} y1={0}>
        <Lines t={t} top={240} size={84} items={[["Seu cliente", 3.04], ["pesquisa no Google", 3.6]]} out={5.62} color={INK} />
        <Lines t={t} top={240} size={92} items={[["e acha seu", 5.8], ["concorrente", 6.5, true]]} out={7.5} color={INK} hlBg={BLACK} hlColor={OR} />
        <Lines t={t} top={230} size={118} items={[["não você.", 7.62, true]]} hlBg={RED} hlColor={WHITE} />
        <div style={{ position: "absolute", left: 120, top: 560, width: 840, height: 130, borderRadius: 130, background: WHITE, boxShadow: SHADOW, display: "flex", alignItems: "center", gap: 26, padding: "0 44px", boxSizing: "border-box", fontFamily: F, fontWeight: 600, fontSize: 50, color: "#222", opacity: k(t, T2 + 0.05, 0.4), transform: `translateY(${((1 - k(t, T2 + 0.05, 0.5)) * 80).toFixed(1)}px)` }}>
          <IcoSearch s={56} c="#555" />
          <span>{typed}<span style={{ opacity: Math.sin(t * 12) > 0 && t < 5.2 ? 1 : 0, color: OR }}>|</span></span>
        </div>
        {["Concorrente", "Concorrente", "Concorrente"].map((n, i) => {
          const at = 4.75 + i * 0.22;
          const e = pop(t, at, 0.45);
          const top = 780 + i * 200;
          return (
            <React.Fragment key={i}>
              <SlotNum n={i + 1} top={top} on={false} light style={{ opacity: Math.min(1, e * 2) }} />
              <Card name={n} light style={{ top, opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * 140).toFixed(1)}px)` }} />
            </React.Fragment>
          );
        })}
        <div style={{ position: "absolute", left: 0, right: 0, top: 1440, height: 6, opacity: lin(t, 7.5, 7.7) }}>
          {[...Array(3)].map((_, i) => <div key={i} style={{ position: "absolute", left: 525 + (i - 1) * 40, width: 14, height: 14, borderRadius: 14, background: "#C9C5BC" }} />)}
        </div>
        <Card name="Sua empresa" you light dim={lose} style={{ top: 1500 + lose * 60, opacity: Math.min(1, pop(t, 7.55, 0.4) * 2) }} />
        <div style={{ position: "absolute", left: 890, top: 1475 + lose * 60, width: 96, height: 96, borderRadius: 96, background: RED, color: WHITE, fontFamily: F, fontWeight: 800, fontSize: 60, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, 7.85, 0.4).toFixed(3)})` }}>✕</div>
      </Cam>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · a arte do GMN Tope 03 abre em círculo ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const r = io(t, 8.85, 9.45);
  const flash = bump(t, 9.1, 0.45);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <div style={{ position: "absolute", left: 540 - 60, top: 960 - 60, width: 120, height: 120, borderRadius: 120, background: OR, transform: `scale(${(pop(t, T3 + 0.05, 0.35) * (1 - r)).toFixed(3)})`, boxShadow: `0 0 80px ${OR}` }} />
      <div style={{ position: "absolute", inset: 0, clipPath: `circle(${(r * 75).toFixed(2)}% at 50% 50%)` }}>
        <Img src={staticFile("digitall/foto-1.jpg")} style={{ position: "absolute", left: (1080 - 1150) / 2, top: 960 - 479, width: 1150, transform: `scale(${(1.18 - 0.18 * io(t, 8.85, 10.7)).toFixed(4)})` }} />
      </div>
      <AbsoluteFill style={{ background: WHITE, opacity: flash * 0.55 }} />
    </AbsoluteFill>
  );
};

// ───────── cena 4 · sobe para o TOP 3 ─────────
const S4: React.FC<{ t: number }> = ({ t }) => {
  const climb = io(t, 11.3, 12.0);
  const others = ["Concorrente", "Concorrente", "Concorrente"];
  const slot = (i: number) => 760 + i * 200;
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Cam t={t} a={T4} b={T5 + 0.4} s0={1.0} s1={1.06} y0={20} y1={-10}>
        <Lines t={t} top={210} size={96} items={[["te coloca no", 10.62]]} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 330, display: "flex", justifyContent: "center", ...blurIn(t, 11.32) }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 210, lineHeight: 1, letterSpacing: "-0.05em", color: OR }}>TOP 3</div>
        </div>
        <Lines t={t} top={560} size={80} items={[["do Google", 11.95]]} />
        {[0, 1, 2, 3].map((i) => <SlotNum key={i} n={i + 1} top={slot(i)} on={i < 3} style={{ opacity: k(t, T4 + 0.05 + i * 0.08, 0.4) }} />)}
        {others.map((n, i) => {
          const y = slot(i) + climb * 200;
          return <Card key={i} name={n} dim={i === 2 ? climb : 0} style={{ top: y, opacity: k(t, T4 + 0.08 + i * 0.08, 0.4) }} />;
        })}
        <Card name="Sua empresa" you style={{ top: slot(3) - climb * 600, opacity: k(t, T4 + 0.3, 0.4), zIndex: 2, transform: `scale(${(1 + 0.06 * Math.sin(climb * Math.PI)).toFixed(4)})`, boxShadow: climb > 0 ? `0 0 ${(70 * climb).toFixed(0)}px rgba(242,159,5,0.35)` : undefined }} />
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 5 · em 7 dias: o checklist do produto ─────────
const S5: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BLACK }}>
    <Screen src="foto-3.jpg" t={t} a={T5} b={T6 + 0.4} pos0="0 50" pos1="0 50" s0={1.0} s1={1.18} origin="0% 30%" />
    <Letter t={t} text="em 7 dias" at={12.6} size={150} top={1340} />
    <div style={{ position: "absolute", left: 160, top: 1630, width: 760, display: "flex", gap: 14 }}>
      {[...Array(7)].map((_, i) => {
        const on = lin(t, 12.85 + i * 0.12, 12.95 + i * 0.12);
        return (
          <div key={i} style={{ flex: 1, textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: 34, color: on > 0.5 ? OR : "#4A4A4A" }}>
            <div style={{ height: 18, borderRadius: 18, background: on > 0.5 ? OR : "#2A2A2A", marginBottom: 14, transform: `scaleY(${(1 + 0.5 * bump(t, 12.85 + i * 0.12, 0.25)).toFixed(3)})` }} />
            D{i + 1}
          </div>
        );
      })}
    </div>
  </AbsoluteFill>
);

// ───────── cena 6 · sem anúncio, sem enrolação: o painel do produto ─────────
const S6: React.FC<{ t: number }> = ({ t }) => {
  const sw = io(t, 15.1, 15.45);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <Screen src="foto-7.jpg" t={t} a={T6} b={15.5} pos0="4 50" pos1="22 50" s0={1.0} s1={1.08} />
      <div style={{ position: "absolute", inset: 0, clipPath: `inset(0 0 0 ${((1 - sw) * 100).toFixed(2)}%)` }}>
        <AbsoluteFill style={{ background: BLACK }} />
        <Screen src="foto-2.jpg" t={t} a={15.1} b={T7 + 0.4} pos0="0 10" pos1="8 40" s0={1.06} s1={1.0} />
      </div>
      <Letter t={t} text="Sem anúncio" at={14.15} out={15.08} size={130} top={1400} />
      <Letter t={t} text="sem enrolação" at={15.27} size={120} top={1400} />
    </AbsoluteFill>
  );
};

// ───────── cena 7 · aparecer e vender: o perfil certo no Google ─────────
